import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main()=>runApp(MaterialApp(theme:ThemeData(colorSchemeSeed:const Color(0xff7943df),useMaterial3:true),home:const WalletApp()));
class WalletApp extends StatefulWidget{const WalletApp({super.key});@override State<WalletApp> createState()=>_WalletState();}
class _WalletState extends State<WalletApp>{final origin=TextEditingController(),org=TextEditingController(),email=TextEditingController(),password=TextEditingController(),amount=TextEditingController(text:'20');String token='',message='Connect your customer account.',method='';bool pending=false;Map<String,dynamic>? wallet;List<dynamic> methods=[],payouts=[];
Future<dynamic> call(String path,{Map<String,dynamic>? body})async{final uri=Uri.parse('${origin.text.replaceAll(RegExp(r'/$'),'')}$path');final headers={'orgid':org.text,'Content-Type':'application/json',if(token.isNotEmpty)'Authorization':'Bearer $token'};final r=body==null?await http.get(uri,headers:headers):await http.post(uri,headers:headers,body:jsonEncode(body));final j=jsonDecode(r.body);if(r.statusCode>=400)throw Exception(j['message']??j['error']??'Request failed');return j;}
Future<void> refresh()async{final m=await call('/client/finance/payout-methods');final w=await call('/client/finance/wallet');final p=await call('/client/finance/payouts?page=1&pageSize=20');if(!mounted)return;setState((){methods=m;wallet=w;payouts=p['data']??[];if(!methods.any((x)=>x['id']==method))method=methods.isEmpty?'':methods.first['id'];});}
Future<void> run(Future<void>Function() work)async{if(pending)return;setState(()=>pending=true);try{await work();}catch(e){if(mounted)setState(()=>message=e.toString());}finally{if(mounted)setState(()=>pending=false);}}
Widget field(String label,TextEditingController c,{bool obscure=false})=>Padding(padding:const EdgeInsets.only(bottom:16),child:TextField(controller:c,obscureText:obscure,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
String money(dynamic x)=>'\$${(x as num? ?? 0).toStringAsFixed(2)}';
@override void dispose(){for(final c in[origin,org,email,password,amount]){c.dispose();}super.dispose();}
@override Widget build(BuildContext context){final d=wallet?['wallet']?['data']??{};final s=wallet?['summary']??{};return Scaffold(appBar:AppBar(title:const Text('AppEngine wallet')),body:ListView(padding:const EdgeInsets.all(24),children:[if(token.isEmpty)...[field('Assigned HTTPS AppEngine backend',origin),field('Organization',org),field('Customer email',email),field('Password',password,obscure:true),FilledButton(onPressed:pending?null:()=>run(()async{final result=await call('/profile/customer/signin',body:{'email':email.text,'password':password.text});if(result['token']==null)throw Exception('Complete the returned sign-in challenge before continuing.');token=result['token'];password.clear();await refresh();setState(()=>message='Customer account connected.');}),child:const Text('Sign in'))]else...[for(final row in[['Total',d['balance']],['Held',d['heldBalance']],['Reserved',d['reservedBalance']],['Available',s['availableBalance']]])Card(child:ListTile(title:Text(row[0].toString()),trailing:Text(money(row[1]),style:Theme.of(context).textTheme.titleLarge))),const SizedBox(height:22),DropdownButtonFormField<String>(initialValue:method.isEmpty?null:method,items:methods.map((m)=>DropdownMenuItem<String>(value:m['id'],child:Text('${m['label']} · ${m['status']}',overflow:TextOverflow.ellipsis))).toList(),onChanged:pending?null:(v)=>setState(()=>method=v??''),decoration:const InputDecoration(labelText:'Saved destination')),const SizedBox(height:20),field('Payout amount · USD',amount),FilledButton(onPressed:pending||method.isEmpty?null:()=>run(()async{final value=double.tryParse(amount.text);if(value==null||value<=0)throw Exception('Enter a positive amount.');final p=await call('/client/finance/payouts/request',body:{'amount':value,'methodId':method});await refresh();setState(()=>message='Request ${p['data']['status']}; inspect reserved funds.');}),child:const Text('Request payout')),TextButton(onPressed:pending?null:()=>run(refresh),child:const Text('Refresh saved states')),const Text('Your payout requests'),for(final p in payouts)ListTile(title:Text(money(p['data']['amount'])),subtitle:Text(p['data']['method']),trailing:Text(p['data']['status'])),const Text('This customer app cannot approve or process payouts. Add a verified destination through the full browser example.')],const SizedBox(height:20),if(pending)const LinearProgressIndicator(),Text(message)]));}}
